    g.beginPath(); g.moveTo(px, 0); g.lineTo(px, H); g.stroke();
  }
  for (const z of [-120, -80, -40, 0, 40, 80, 120]) {
    const py = 10 + ((z + 160) / 320) * 180;
    g.beginPath(); g.moveTo(0, py); g.lineTo(156, py); g.stroke();
  }
  // jalan pantai
  g.strokeStyle = '#7a8494'; g.lineWidth = 6;
