  }
  // kompas + skala
  g.fillStyle = '#cfe6ff'; g.font = 'bold 13px Arial'; g.textAlign = 'left';
  g.fillText('U ▲', 14, 24);
  g.strokeStyle = '#cfe6ff'; g.lineWidth = 2;
  g.beginPath(); g.moveTo(14, H - 22); g.lineTo(14 + 50 * SX, H - 22); g.stroke();
  g.fillText('50 m', 14, H - 30);
}
